In Swift, you can create a similar class using `CALayer` and `UIImage` for the drawables. Here's a basic example:

```swift
import UIKit

class StackedLayers {
    private var layers: [CALayer] = []
    private let iconScale: CGFloat = 0.7

    init(layers: [UIImage], iconScale: CGFloat = 0.7) {
        self.layers = layers.map { layer(from: $0, scale: iconScale) }
    }

    func layer(from image: UIImage, scale: CGFloat) -> CALayer {
        let layer = CALayer()
        let size = image.size.applying(CGAffineTransform(scaleX: scale, y: scale))
        layer.frame = CGRect(origin: .zero, size: size)
        layer.contents = image.cgImage
        return layer
    }

    func stackLayers(on view: UIView) {
        let stackView = UIStackView(arrangedSubviews: layers)
        stackView.axis = .vertical
        stackView.distribution = .fillEqually
        stackView.spacing = 0
        view.addSubview(stackView)
        NSLayoutConstraint.activate([
            stackView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            stackView.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            stackView.topAnchor.constraint(equalTo: view.topAnchor),
            stackView.bottomAnchor.constraint(equalTo: view.bottomAnchor)
        ])
    }
}
```

